  1	export const PLANNER_WINDOW_RADIUS_MINUTES = 10;
  2	export const MINUTES_PER_DAY = 24 * 60;
  3	export const MINIMUM_COMPARISON_DATES = 4;
  4	export const MINIMUM_COMPARISON_CANDIDATES = 3;
  5	
  6	export type WeekdayEvidence = Readonly<{
  7	  labelDate: string;
  8	  labelMinute: number;
  9	}>;
 10	
 11	// biome-ignore lint/style/useConsistentTypeDefinitions: AGENTS.md prefers types unless extending.
 12	type PlannerStateBase = {
 13	  candidateCount: number;
 14	  historicalDateCount: number;
 15	  selectedDateCount: number;
 16	};
 17	
 18	export type VisitPlan =
 19	  | (PlannerStateBase & { state: "no-weekday-history" })
 20	  | (PlannerStateBase & { state: "zero-selected-matches" })
 21	  | (PlannerStateBase & { state: "insufficient-comparison" })
 22	  | (PlannerStateBase & {
 23	      candidateScores: number[];
 24	      signal: "better" | "typical" | "quieter";
 25	      state: "comparative";
 26	    });
 27	
 28	export function calculateVisitPlan(
 29	  evidence: readonly WeekdayEvidence[],
 30	  selectedMinute: number
 31	): VisitPlan {
 32	  const distinctEvidence = getDistinctEvidence(evidence);
 33	  const historicalDateCount = new Set(
 34	    distinctEvidence.map(({ labelDate }) => labelDate)
 35	  ).size;
 36	  const candidateMinutes = Array.from(
 37	    new Set(distinctEvidence.map(({ labelMinute }) => labelMinute))
 38	  ).sort((first, second) => first - second);
 39	  const selectedDateCount = scoreWindow(distinctEvidence, selectedMinute);
 40	  const candidateScores = candidateMinutes.map((minute) =>
 41	    scoreWindow(distinctEvidence, minute)
 42	  );
 43	
 44	  return calculatePlannerSignal({
 45	    candidateScores,
 46	    historicalDateCount,
 47	    selectedDateCount,
 48	  });
 49	}
 50	
 51	export function calculatePlannerSignal({
 52	  candidateScores,
 53	  historicalDateCount,
 54	  selectedDateCount,
 55	}: Readonly<{
 56	  candidateScores: readonly number[];
 57	  historicalDateCount: number;
 58	  selectedDateCount: number;
 59	}>): VisitPlan {
 60	  const candidateCount = candidateScores.length;
 61	  const base = {
 62	    candidateCount,
 63	    historicalDateCount,
 64	    selectedDateCount,
 65	  };
 66	
 67	  if (historicalDateCount === 0) {
 68	    return { ...base, state: "no-weekday-history" };
 69	  }
 70	
 71	  if (selectedDateCount === 0) {
 72	    return { ...base, state: "zero-selected-matches" };
 73	  }
 74	
 75	  if (
 76	    historicalDateCount < MINIMUM_COMPARISON_DATES ||
 77	    candidateCount < MINIMUM_COMPARISON_CANDIDATES
 78	  ) {
 79	    return { ...base, state: "insufficient-comparison" };
 80	  }
 81	
 82	  const lowerScoreCount = candidateScores.filter(
 83	    (candidateScore) => candidateScore < selectedDateCount
 84	  ).length;
 85	  const higherScoreCount = candidateScores.filter(
 86	    (candidateScore) => candidateScore > selectedDateCount
 87	  ).length;
 88	  let signal: "better" | "typical" | "quieter" = "typical";
 89	  if (3 * lowerScoreCount >= 2 * candidateCount) {
 90	    signal = "better";
 91	  } else if (3 * higherScoreCount >= 2 * candidateCount) {
 92	    signal = "quieter";
 93	  }
 94	
 95	  return {
 96	    ...base,
 97	    candidateScores: [...candidateScores],
 98	    signal,
 99	    state: "comparative",
100	  };
101	}
102	
103	function getDistinctEvidence(
104	  evidence: readonly WeekdayEvidence[]
105	): WeekdayEvidence[] {
106	  const seenEvidence = new Set<string>();
107	  const distinctEvidence: WeekdayEvidence[] = [];
108	
109	  for (const entry of evidence) {
110	    const evidenceKey = `${entry.labelDate}\u0000${entry.labelMinute}`;
111	    if (seenEvidence.has(evidenceKey)) {
112	      continue;
113	    }
114	
115	    seenEvidence.add(evidenceKey);
116	    distinctEvidence.push(entry);
117	  }
118	
119	  return distinctEvidence;
120	}
121	
122	function scoreWindow(
123	  evidence: readonly WeekdayEvidence[],
124	  centerMinute: number
125	): number {
126	  const windowStart = Math.max(0, centerMinute - PLANNER_WINDOW_RADIUS_MINUTES);
127	  const windowEnd = Math.min(
128	    MINUTES_PER_DAY - 1,
129	    centerMinute + PLANNER_WINDOW_RADIUS_MINUTES
130	  );
131	  const matchingDates = new Set<string>();
132	
133	  for (const entry of evidence) {
134	    if (entry.labelMinute >= windowStart && entry.labelMinute <= windowEnd) {
135	      matchingDates.add(entry.labelDate);
136	    }
137	  }
138	
139	  return matchingDates.size;
140	}
